applied_count = 0
for i, (target, repl) in enumerate(replacements):
    if target in text:
        text = text.replace(target, repl)
        applied_count += 1
        print(f"Applied replacement {i+1}")
    else:
        # Check if first 50 chars match
        prefix = target[:50]
        if prefix in text:
            print(f"FAILED partial match on {i+1}: prefix found but full target differs!")
        else:
            print(f"FAILED on {i+1}: prefix '{prefix}' not found!")

with open(TARGET_FILE, "w", encoding="utf-8") as f:
    f.write(text)

print(f"Total replacements applied: {applied_count} / {len(replacements)}")
